import { graphql, navigate } from "gatsby";
import React from "react";
import { AdminLayout } from "../../../features/admin/components/AdminLayout";
import { ItineraryList } from "../../../features/admin/components/ItineraryList";

export default function ItinerariesPage() {
  return (
    <AdminLayout title="Itineraries">
      <div className="mb-5 flex items-center justify-between">
        <p className="text-sm text-gray-500">Create and manage travel itineraries.</p>
        <button
          onClick={() => navigate("/admin/itineraries/new")}
          className="rounded-lg bg-gray-900 px-4 py-2 text-sm font-medium text-white transition hover:bg-gray-700"
        >
          + New itinerary
        </button>
      </div>
      <ItineraryList />
    </AdminLayout>
  );
}
export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;