import { navigate } from "gatsby";
import React, { useEffect, useState } from "react";
import type { Itinerary, ItineraryStatus } from "../types";
import { listItineraries } from "../../../sessionServices/itineraries/itinerariesService";

const STATUS_BADGE: Record<ItineraryStatus, string> = {
  draft: "bg-gray-100 text-gray-600",
  in_review: "bg-yellow-100 text-yellow-700",
  approved: "bg-blue-100 text-blue-700",
  shared: "bg-green-100 text-green-700",
  in_follow_up: "bg-purple-100 text-purple-700",
  closed: "bg-red-100 text-red-600",
};

type ItineraryWithId = Itinerary & { id: string };

export function ItineraryList() {
  const [itineraries, setItineraries] = useState<ItineraryWithId[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    listItineraries()
      .then(setItineraries)
      .catch(() => setError("Failed to load itineraries."))
      .finally(() => setLoading(false));
  }, []);

  if (loading) {
    return (
      <div className="flex items-center justify-center py-16">
        <div className="h-6 w-6 animate-spin rounded-full border-4 border-gray-300 border-t-gray-800" />
      </div>
    );
  }

  if (error) {
    return <div className="rounded-lg bg-red-50 px-4 py-3 text-sm text-red-600">{error}</div>;
  }

  if (itineraries.length === 0) {
    return (
      <div className="rounded-xl bg-white py-12 text-center ring-1 ring-gray-200">
        <p className="text-sm text-gray-500">No itineraries yet.</p>
      </div>
    );
  }

  return (
    <div className="overflow-hidden rounded-xl bg-white shadow-sm ring-1 ring-gray-200">
      <table className="min-w-full divide-y divide-gray-100">
        <thead>
          <tr className="bg-gray-50">
            <th className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">Title</th>
            <th className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">Destinations</th>
            <th className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">Dates</th>
            <th className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">Travelers</th>
            <th className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">Status</th>
            <th className="px-4 py-3" />
          </tr>
        </thead>
        <tbody className="divide-y divide-gray-100">
          {itineraries.map((it) => (
            <tr key={it.id} className="hover:bg-gray-50">
              <td className="px-4 py-3 text-sm font-medium text-gray-900">{it.title}</td>
              <td className="px-4 py-3 text-sm text-gray-600">
                {it.destinationCities.join(", ") || "—"}
              </td>
              <td className="px-4 py-3 text-sm text-gray-600 whitespace-nowrap">
                {formatDate(it.startDate)} – {formatDate(it.endDate)}
              </td>
              <td className="px-4 py-3 text-sm text-gray-600">{it.travelerCount}</td>
              <td className="px-4 py-3">
                <span className={`inline-flex rounded-full px-2 py-0.5 text-xs font-medium ${STATUS_BADGE[it.status]}`}>
                  {it.status.replace("_", " ")}
                </span>
              </td>
              <td className="px-4 py-3 text-right">
                <button
                  onClick={() => navigate(`/admin/itineraries/${it.id}`)}
                  className="mr-3 text-xs text-gray-500 underline hover:text-gray-900"
                >
                  View
                </button>
                <button
                  onClick={() => navigate(`/admin/itineraries/${it.id}/edit`)}
                  className="text-xs text-gray-500 underline hover:text-gray-900"
                >
                  Edit
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

function formatDate(ts: unknown): string {
  if (!ts) return "—";
  try {
    const date = (ts as { toDate: () => Date }).toDate();
    return date.toLocaleDateString("en-CA");
  } catch {
    return "—";
  }
}
